#!/usr/bin/env bash
# benchmarks/queue/T_CV5_convergence_ngl_sweep.sh
# Generated by Antigravity for BENCH_05

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
TIMESTAMP=$(date -u +%Y%m%dT%H%M%SZ)
RESULTS_DIR="${REPO_ROOT}/results/T_CV5_ngl_sweep_${TIMESTAMP}"
mkdir -p "${RESULTS_DIR}"

PROMPT="Explain the architecture of a transformer model in detail, covering attention mechanisms, feed-forward layers, positional encoding, and the encoder-decoder structure."

echo "Results directory: ${RESULTS_DIR}"
echo "ngl,rep,tokens,elapsed_s,tps,gpu0_vram,gpu1_vram" > "${RESULTS_DIR}/raw.csv"

for NGL in 10 20 35 50; do
    echo "--- Testing NGL=${NGL} ---"
    
    # Stop current Convergence
    CONV_CONTAINER=$(podman ps --format "{{.Names}}" | grep -i "convergence\|ikllamacpp" | head -1)
    if [ -n "${CONV_CONTAINER}" ]; then
        echo "Stopping: ${CONV_CONTAINER}"
        podman stop "${CONV_CONTAINER}" && podman rm "${CONV_CONTAINER}"
        sleep 3
    fi

    # Deploy with new -ngl
    VLLM_V1_ENABLED=0 \
    "${REPO_ROOT}/infra/scripts/deploy.sh" ikllamacpp convergence "${CONVERGENCE_MODEL}" \
      -- -ngl ${NGL} --cpu-moe -t 32 -np 1 -c 4096

    # Wait for health
    echo "Waiting for health..."
    for i in $(seq 1 120); do
        if curl -sf http://localhost:8002/health &>/dev/null; then
            echo "READY at ngl=${NGL}"
            break
        fi
        sleep 1
        if [ $i -eq 120 ]; then
            echo "TIMEOUT waiting for NGL=${NGL}"
            exit 1
        fi
    done

    # Record VRAM
    VRAM=$(nvidia-smi --query-gpu=index,memory.used --format=csv,noheader,nounits)
    GPU0_VRAM=$(echo "${VRAM}" | grep "^0," | cut -d',' -f2 | xargs)
    GPU1_VRAM=$(echo "${VRAM}" | grep "^1," | cut -d',' -f2 | xargs)

    # Run 3 reps
    for REP in 1 2 3; do
        START_MS=$(date +%s%3N)
        RESPONSE=$(curl -sf http://localhost:8002/v1/completions \
            -H "Content-Type: application/json" \
            -d "{
                \"model\": \"convergence\",
                \"prompt\": \"${PROMPT}\",
                \"max_tokens\": 200,
                \"temperature\": 0.0
            }")
        END_MS=$(date +%s%3N)
        ELAPSED_S=$(python3 -c "print(($END_MS - $START_MS) / 1000.0)")
        TOKENS=$(echo "${RESPONSE}" | python3 -c "import sys, json; d = json.load(sys.stdin); print(d['usage']['completion_tokens'])")
        TPS=$(python3 -c "print(round(${TOKENS} / ${ELAPSED_S}, 2))")
        echo "ngl=${NGL} rep=${REP}: ${TOKENS} tokens in ${ELAPSED_S}s = ${TPS} t/s (VRAM: ${GPU0_VRAM}/${GPU1_VRAM})"
        echo "${NGL},${REP},${TOKENS},${ELAPSED_S},${TPS},${GPU0_VRAM},${GPU1_VRAM}" >> "${RESULTS_DIR}/raw.csv"
    done
done

echo "Sweep complete. Results in ${RESULTS_DIR}/raw.csv"
